        @font-face { font-family: "Geist"; src: url("../assets/fonts/geist-sans-latin-700-normal.woff2") format("woff2"); font-weight: 700; }
        @font-face { font-family: "Geist Mono"; src: url("../assets/fonts/geist-mono-latin-500-normal.woff2") format("woff2"); font-weight: 500; }
        #root { position: absolute; inset: 0; overflow: hidden; pointer-events: none; font-family: "Geist", sans-serif; }
        #wf-back { position: absolute; inset: 0; background: rgba(245,247,251,.97); opacity: 0; }
        #wf-stage { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; transform-origin: 0 0; }
        #wf-stage svg { width: 1920px; height: 1080px; overflow: visible; }
        .nt { font-family: "Geist", sans-serif; font-weight: 700; font-size: 30px; }
        .ns { font-family: "Geist", sans-serif; font-weight: 500; font-size: 21px; }
        .el { font-family: "Geist Mono", monospace; font-size: 22px; }
        #wf-head { position: absolute; left: 120px; top: 96px; opacity: 0; }
        #wf-kicker { font-family: "Geist Mono", monospace; font-size: 24px; letter-spacing: .14em; color: #6b7a8f; }
        #wf-title { position: relative; height: 110px; margin-top: 8px; width: 1500px; }
        .ttl { position: absolute; left: 0; top: 0; font-family: "Instrument Serif", serif; font-size: 96px; color: #0d1b2a; opacity: 0; white-space: nowrap; letter-spacing: -0.015em; }
        .ttl em { font-style: italic; }
      </style>
      <div id="root" data-composition-id="workflow" data-width="1920" data-height="1080">
        <div id="wf-back"></div>
        <div id="wf-head">
          <div id="wf-kicker">HOW DIXI DECIDES</div>
          <div id="wf-title">
            <div class="ttl" id="wf-t1">Layer 1 · <em style="color:#0f3d75">Principles</em></div>
            <div class="ttl" id="wf-t2">Layer 2 · <em style="color:#1c69d4">Evidence</em></div>
            <div class="ttl" id="wf-t3">A human decides. <em style="color:#e22718">Memory keeps it.</em></div>
            <div class="ttl" id="wf-t4">Layer 3 · <em style="color:#5aa9f0">Profiles</em></div>
            <div class="ttl" id="wf-t5">Every weight is <em style="color:#1c69d4">yours.</em></div>
          </div>
        </div>
        <div id="wf-stage">
          <svg viewBox="0 0 1920 1080">
            <defs>
              <filter id="wf-glow" x="-40%" y="-40%" width="180%" height="180%"><feGaussianBlur stdDeviation="14" /></filter>
              <marker id="wf-ar" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 z" fill="#7d8da3" /></marker>
              <marker id="wf-arR" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 z" fill="#e22718" /></marker>
            </defs>
            <rect id="wf-card" x="-30" y="150" width="1980" height="800" rx="60" fill="#ffffff" stroke="#c9d4e3" stroke-width="6" opacity="0" />
            <g id="wf-edges"></g>
            <g id="wf-nodes"></g>
          </svg>
        </div>
      </div>
      <script>
        (function () {
          const tl = gsap.timeline({ paused: true });
          const ns = "http://www.w3.org/2000/svg";
          const W = 236, H = 124;
          const N = {
            n1: { x: 150, y: 520, t: "L1 · Principles", s: "owned by PMs", c: "#0f3d75", soft: "#e6edf6" },
            n2: { x: 420, y: 520, t: "L2 · Evidence", s: "feedback · trends", c: "#1c69d4", soft: "#eaf2fd" },
            n3: { x: 690, y: 520, t: "Requests", s: "clustered · scored", c: "#1c69d4", soft: "#eaf2fd" },
            n4: { x: 960, y: 520, t: "PM gate", s: "keep / reject + why", c: "#e22718", soft: "#fdecea", human: true },
            n5: { x: 1230, y: 520, t: "L3 · Profiles", s: "3 per market", c: "#5aa9f0", soft: "#eaf5fe" },
            n6: { x: 1500, y: 520, t: "Social test", s: "noisy signal", c: "#5aa9f0", soft: "#eaf5fe" },
            n7: { x: 1770, y: 520, t: "Recommend", s: "traceable", c: "#0f3d75", soft: "#e6edf6" },
            n8: { x: 960, y: 800, w: 330, t: "Decision memory", s: "remembers every why", c: "#e22718", soft: "#fdecea", human: true },
            n9: { x: 1095, y: 270, t: "Source weights", s: "set by the PM", c: "#1c69d4", soft: "#eaf2fd" }
          };
          const gN = document.getElementById("wf-nodes"), gE = document.getElementById("wf-edges");
          const el = (tag, attrs, parent) => { const e = document.createElementNS(ns, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); return e; };
          for (const id in N) {
            const n = N[id];
            const g = el("g", { id: "wf-" + id }, gN);
            const nw = n.w || W;
            n.glow = el("rect", { x: n.x - nw / 2, y: n.y - H / 2, width: nw, height: H, rx: 26, fill: n.c, filter: "url(#wf-glow)", opacity: 0 }, g);
            n.box = el("rect", { x: n.x - nw / 2, y: n.y - H / 2, width: nw, height: H, rx: 26, fill: "#ffffff", stroke: n.human ? "#e22718" : "#c9d4e3", "stroke-width": 4 }, g);
            n.tt = el("text", { x: n.x, y: n.y - 6, "text-anchor": "middle", class: "nt", fill: "#0d1b2a" }, g); n.tt.textContent = n.t;
            n.st = el("text", { x: n.x, y: n.y + 30, "text-anchor": "middle", class: "ns", fill: "#5d6b80" }, g); n.st.textContent = n.s;
          }
          const E = [];
          const edge = (id, d, red, dash, label, lx, ly, sw) => {
            const p = el("path", { id: "wf-" + id, d, fill: "none", stroke: red ? "#e22718" : "#7d8da3", "stroke-width": sw || 4, "marker-end": red ? "url(#wf-arR)" : "url(#wf-ar)", "stroke-linecap": "round" }, gE);
            const len = p.getTotalLength();
            p.setAttribute("stroke-dasharray", dash ? "14 12" : len + " " + len);
            p.setAttribute("stroke-dashoffset", dash ? 0 : len);
            p.setAttribute("opacity", 0);
            let lab = null;
            if (label) { lab = el("text", { x: lx, y: ly, "text-anchor": "middle", class: "el", fill: red ? "#c81e10" : "#3b4a5c", opacity: 0 }, gE); lab.textContent = label; }
            E[id] = { p, len, dash, lab };
          };
          const r = W / 2;
          edge("e1", `M${150 + r} 520 L${420 - r - 6} 520`);
          edge("e2", `M${420 + r} 520 L${690 - r - 6} 520`);
          edge("e3", `M${690 + r} 520 L${960 - r - 6} 520`);
          edge("e4", `M${960 + r} 520 L${1230 - r - 6} 520`);
          edge("e5", `M${1230 + r} 520 L${1500 - r - 6} 520`);
          edge("e6", `M${1500 + r} 520 L${1770 - r - 6} 520`);
          edge("e7", `M960 ${520 + H / 2} L960 ${800 - H / 2 - 6}`, true, false, "reject + reason", 1080, 670);
          edge("e8", `M${960 - 165} 800 C 720 800, 690 740, 690 ${520 + H / 2 + 8}`, true, true, "next generation", 560, 700);
          edge("e9", `M${1095 - 60} ${270 + H / 2} C 1000 380, 760 380, 712 ${520 - H / 2 - 6}`, false, false, "L2 · high", 880, 352, 7);
          edge("e10", `M${1095 + 60} ${270 + H / 2} C 1200 380, 1440 380, 1480 ${520 - H / 2 - 6}`, false, false, "L3 · low", 1340, 352, 2);
          edge("e11", `M${150} ${520 - H / 2} C 150 300, 960 300, 950 ${520 - H / 2 - 6}`, false, false, "checked first", 520, 330);
          const draw = (id, t, d) => {
            const e = E[id];
            if (e.dash) tl.fromTo(e.p, { opacity: 0 }, { opacity: 1, duration: d || 0.5 }, t);
            else { tl.fromTo(e.p, { opacity: 0 }, { opacity: 1, duration: 0.15 }, t); tl.fromTo(e.p, { attr: { "stroke-dashoffset": e.len } }, { attr: { "stroke-dashoffset": 0 }, duration: d || 0.6, ease: "power2.inOut" }, t); }
            if (e.lab) tl.fromTo(e.lab, { opacity: 0 }, { opacity: 1, duration: 0.4 }, t + 0.3);
          };
          const on = (id, t) => {
            const n = N[id];
            tl.to(n.box, { attr: { fill: n.c, stroke: n.c }, duration: 0.35, ease: "power2.out" }, t);
            tl.to([n.tt, n.st], { attr: { fill: "#ffffff" }, duration: 0.35 }, t);
            tl.to(n.glow, { opacity: 0.55, duration: 0.4 }, t);
            tl.fromTo("#wf-" + id, { scale: 1, transformOrigin: n.x + "px " + n.y + "px" }, { scale: 1.08, duration: 0.25, ease: "power2.out", yoyo: true, repeat: 1 }, t);
          };
          const visited = (id, t) => {
            const n = N[id];
            tl.to(n.box, { attr: { fill: n.soft, stroke: n.c }, duration: 0.35 }, t);
            tl.to(n.tt, { attr: { fill: "#0d1b2a" }, duration: 0.35 }, t);
            tl.to(n.st, { attr: { fill: "#3b4a5c" }, duration: 0.35 }, t);
            tl.to(n.glow, { opacity: 0, duration: 0.3 }, t);
          };
          // full ↔ mini camera states
          const MINI = { x: 1496, y: 128, scale: 0.21 };
          const toFull = (t, title) => {
            tl.to("#wf-stage", { x: 125, y: 110, scale: 0.87, duration: 0.6, ease: "expo.inOut" }, t);
            tl.to("#wf-back", { opacity: 1, duration: 0.45 }, t);
            tl.to("#wf-card", { opacity: 0, duration: 0.3 }, t);
            tl.to("#wf-head", { opacity: 1, duration: 0.3 }, t + 0.25);
            tl.fromTo(title, { opacity: 0, y: 26 }, { opacity: 1, y: 0, duration: 0.5, ease: "power3.out" }, t + 0.3);
          };
          const toMini = (t, title) => {
            tl.to(title, { opacity: 0, duration: 0.25 }, t);
            tl.to("#wf-head", { opacity: 0, duration: 0.25 }, t);
            tl.to("#wf-back", { opacity: 0, duration: 0.5 }, t + 0.1);
            tl.to("#wf-stage", { x: MINI.x, y: MINI.y, scale: MINI.scale, duration: 0.75, ease: "expo.inOut" }, t);
            tl.to("#wf-card", { opacity: 1, duration: 0.4 }, t + 0.3);
          };
          gsap.set("#wf-stage", { x: 125, y: 110, scale: 0.87 });
          // ---- P1 · L1 (global 44.0) ----
          toFull(0, "#wf-t1");
          tl.fromTo("#wf-nodes > g", { opacity: 0, y: 24 }, { opacity: 1, y: 0, duration: 0.45, stagger: 0.05, ease: "back.out(1.6)" }, 0.15);
          on("n1", 0.9); draw("e11", 1.4, 0.9);
          toMini(3.3, "#wf-t1");
          // ---- P2 · L2 (global 58.0) ----
          toFull(14.0, "#wf-t2");
          visited("n1", 14.3); draw("e1", 14.4); on("n2", 14.9); draw("e2", 15.6); on("n3", 16.2);
          toMini(17.3, "#wf-t2");
          visited("n2", 22.0);
          // keep / reject in the recording (global 80.8)
          draw("e3", 36.4); on("n4", 36.8); visited("n3", 36.8);
          // ---- P3 · gate → memory → next generation (global 92.6, hero) → straight into P4 · L3 ----
          toFull(48.6, "#wf-t3");
          draw("e7", 49.3, 0.7); on("n8", 50.0);
          draw("e8", 50.8, 0.6);
          tl.to(N.n3.box, { attr: { fill: N.n3.c, stroke: "#e22718" }, duration: 0.3, yoyo: true, repeat: 1 }, 51.4);
          tl.to(N.n3.glow, { opacity: 0.6, duration: 0.3, yoyo: true, repeat: 1 }, 51.4);
          tl.to("#wf-t3", { opacity: 0, y: -20, duration: 0.3 }, 53.0);
          tl.fromTo("#wf-t4", { opacity: 0, y: 26 }, { opacity: 1, y: 0, duration: 0.5, ease: "power3.out" }, 53.2);
          visited("n4", 53.0); visited("n8", 53.4); draw("e4", 53.7); on("n5", 54.2);
          toMini(56.2, "#wf-t4");
          // hide during the M350 story popup (global 108.8–114.6)
          tl.to("#wf-stage", { opacity: 0, duration: 0.3 }, 64.8);
          tl.to("#wf-stage", { opacity: 1, duration: 0.4 }, 70.6);
          visited("n5", 70.8); draw("e5", 70.9); on("n6", 71.2);
          // ---- P5 · weights (global 126.0) ----
          toFull(82.0, "#wf-t5");
          visited("n6", 82.3); on("n9", 82.6); draw("e9", 83.1, 0.7); draw("e10", 83.3, 0.7);
          toMini(85.6, "#wf-t5");
          draw("e6", 105.0); visited("n9", 105.4); on("n7", 105.4);
          tl.to("#wf-stage", { opacity: 0, duration: 0.6 }, 109.2);
          window.__timelines["workflow"] = tl;
        })();
      </script>
    </template>
  </body>
</html>

