cd /Volumes/PJ/peresjav/hackathons/ehl-final-minuch-2026/Demo/slides/_tools && cat > package.json <<'EOF'
{ "name": "dixi-deck-render", "private": true, "type": "module", "dependencies": { "playwright": "1.49.1" } }
EOF
cat > render.mjs <<'EOF'
// Renders ../dixi-deck.html to ../dixi-deck.pdf (one 1920x1080 page per slide) and PNG pages for QC.
import { chromium } from "playwright";
import { pathToFileURL } from "node:url";
import { resolve, dirname } from "node:path";
import { mkdirSync } from "node:fs";
const here = dirname(new URL(import.meta.url).pathname);
const deck = resolve(here, "../dixi-deck.html");
const outPdf = resolve(here, "../dixi-deck.pdf");
const pngDir = resolve(here, "pages"); mkdirSync(pngDir, { recursive: true });
let browser;
try { browser = await chromium.launch({ channel: "chrome" }); } catch { browser = await chromium.launch(); }
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 });
await page.goto(pathToFileURL(deck).href, { waitUntil: "load" });
const ready = async () => { await page.evaluate(async () => { await document.fonts.ready; await Promise.all([...document.images].map((i) => i.complete ? 0 : new Promise((r) => { i.onload = i.onerror = r; }))); }); };
await ready();
const n = await page.evaluate(() => document.querySelectorAll(".slide").length);
// PNG per slide (screen mode) + overflow check
const issues = [];
for (let i = 1; i <= n; i++) {
  await page.evaluate((k) => { location.hash = "#" + k; show(k - 1); }, i);
  await page.waitForTimeout(150);
  const o = await page.evaluate(() => {
    const s = document.querySelector(".slide.active"); const out = [];
    for (const e of s.querySelectorAll("*")) {
      const r = e.getBoundingClientRect(); if (!r.width) continue;
      const sr = s.getBoundingClientRect(); const sc = sr.width / 1920;
      if (r.right > sr.right + 1 || r.bottom > sr.bottom + 1 || r.left < sr.left - 1) out.push(e.tagName + "." + e.className + " " + Math.round((r.right - sr.left) / sc) + "x" + Math.round((r.bottom - sr.top) / sc));
      if (e.scrollWidth > e.clientWidth + 2 && getComputedStyle(e).overflow === "visible" && e.clientWidth > 0 && e.children.length === 0) out.push("textoverflow " + e.tagName + " " + e.textContent.slice(0, 40));
    }
    return out;
  });
  if (o.length) issues.push(`slide ${i}: ${o.slice(0, 6).join(" | ")}`);
  await page.screenshot({ path: `${pngDir}/p${String(i).padStart(2, "0")}.png` });
}
await page.emulateMedia({ media: "print" });
await ready();
await page.pdf({ path: outPdf, width: "1920px", height: "1080px", printBackground: true, preferCSSPageSize: true, margin: { top: 0, right: 0, bottom: 0, left: 0 } });
await browser.close();
console.log(JSON.stringify({ slides: n, pdf: outPdf, issues }, null, 1));
EOF
npm install --silent --no-audit --no-fund 2>&1 | tail -3; node render.mjs

