      const r = e.getBoundingClientRect(); if (!r.width) continue;
      const sr = s.getBoundingClientRect(); const sc = sr.width / 1920;
      if (r.right > sr.right + 1 || r.bottom > sr.bottom + 1 || r.left < sr.left - 1) out.push(e.tagName + "." + e.className + " " + Math.round((r.right - sr.left) / sc) + "x" + Math.round((r.bottom - sr.top) / sc));
      if (e.scrollWidth > e.clientWidth + 2 && getComputedStyle(e).overflow === "visible" && e.clientWidth > 0 && e.children.length === 0) out.push("textoverflow " + e.tagName + " " + e.textContent.slice(0, 40));
    }
    return out;
  });
  if (o.length) issues.push(`slide ${i}: ${o.slice(0, 6).join(" | ")}`);
  await page.screenshot({ path: `${pngDir}/p${String(i).padStart(2, "0")}.png` });
}
await page.emulateMedia({ media: "print" });
await ready();
await page.pdf({ path: outPdf, width: "1920px", height: "1080px", printBackground: true, preferCSSPageSize: true, margin: { top: 0, right: 0, bottom: 0, left: 0 } });
await browser.close();
